={
  "model": "llama-3.3-70b-versatile",
  "temperature": 0.4,
  "messages": [
    {
      "role": "system",
      "content": "You are a lead qualification assistant for LUX Quality Homes, a premium custom home builder in Kelowna BC. Return a structured JSON response only, no other text. SCORING RULES - follow these exactly: HOT = budget $700k+ AND timeline within 12 months AND message shows clear intent (financing, signed lot, competitor comparison, ready to sign). WARM = budget $500k-$699k OR timeline 12-24 months OR message shows interest but no urgency. COLD = budget under $500k OR timeline beyond 24 months OR vague inquiry. Return exactly this JSON: {\"score\": \"HOT\" or \"WARM\" or \"COLD\", \"reason\": \"one sentence referencing the specific rule that applied\", \"personalized_email_body\": \"Paragraph 1: acknowledge their specific project type, budget, and timeline. No generic openers.\\n\\nParagraph 2: establish LUX credibility - high-end custom homes in the Okanagan, white-glove communication, systems-driven process.\\n\\nParagraph 3: invite them to a 30 minute discovery call.\\n\\n \\n\\nParagraph 4: Warm regards,\\nBrad\\nFounder, LUX Quality Homes\", \"summary\": \"2 sentence internal summary for the sales team\"}"
    },
    {
       "role": "user",
      "content": "=Qualify this lead:\nName: {{ $json.body.name }}\nEmail: {{ $json.body.email }} \nProject Type: {{ $json.body.project_type }} \nBudget: {{ $json.body.budget_range }} \nTimeline: {{ $json.body.timeline }} \nMessage: {{ $json.body.message }}"

    }
  ]
}

parameters.jsCode:
const content = $input.first().json.choices[0].message.content;
const cleaned = content
  .replace(/[\u0000-\u001F\u007F]/g, (char) => {
    if (char === '\n') return '\\n';
    if (char === '\r') return '\\r';
    if (char === '\t') return '\\t';
    return '';
  });
const parsed = JSON.parse(cleaned);
return [{ json: parsed }];

